const payload = $input.first().json;
const ticker = payload.ticker || 'BTC/USDT';
const currentPrice = payload.currentPrice || 64320;
const portfolioEquity = payload.portfolioEquity || 100000;

// Multi-agent signal matrix
const agentVotes = [
  { botId: 'technical-analyst', action: 'BUY', weight: 0.20, confidence: 84 },
  { botId: 'smc-liquidity', action: 'BUY', weight: 0.20, confidence: 88 },
  { botId: 'sentiment-trader', action: 'BUY', weight: 0.15, confidence: 78 },
  { botId: 'volume-breakout', action: 'BUY', weight: 0.15, confidence: 82 },
  { botId: 'fundamental-valuation', action: 'BUY', weight: 0.10, confidence: 72 },
  { botId: 'arbitrage-funding', action: 'HOLD', weight: 0.10, confidence: 65 },
  { botId: 'macro-regime', action: 'BUY', weight: 0.10, confidence: 76 }
];

let buyScore = 0;
let sellScore = 0;
for (const v of agentVotes) {
  const s = (v.confidence / 100) * v.weight;
  if (v.action === 'BUY') buyScore += s;
  else if (v.action === 'SELL') sellScore += s;
}

const consensusAction = buyScore > 0.5 ? 'BUY' : sellScore > 0.5 ? 'SELL' : 'HOLD';
const consensusConfidence = Math.round(Math.max(buyScore, sellScore) * 100);

// Risk clearance
const recommendedSizeUsd = Math.round(portfolioEquity * 0.08);
const stopLoss = Math.round(currentPrice * 0.975 * 100) / 100;
const takeProfit1 = Math.round(currentPrice * 1.038 * 100) / 100;
const takeProfit2 = Math.round(currentPrice * 1.07 * 100) / 100;

return {
  json: {
    ticker,
    currentPrice,
    consensusAction,
    consensusConfidence,
    entryTarget: currentPrice,
    stopLoss,
    takeProfit1,
    takeProfit2,
    recommendedSizeUsd,
    riskClearance: 'APPROVED',
    agentVotes
  }
};

const prev = $input.first().json;
const text = prev.content || prev.output || JSON.stringify(prev);

return {
  json: {
    success: true,
    botId: 'trading-orchestrator',
    botName: 'Autonomous Hedge Fund Consensus Swarm Master',
    status: 'EXECUTION_DIRECTIVE_COMPILED',
    executionDirective: text,
    brokerPayloads: {
      alpaca: {
        symbol: 'BTCUSD',
        qty: 0.12,
        side: 'buy',
        type: 'limit',
        time_in_force: 'gtc'
      },
      binance: {
        symbol: 'BTCUSDT',
        side: 'BUY',
        type: 'LIMIT',
        quantity: 0.12
      }
    },
    timestamp: new Date().toISOString()
  }
};
